// Parse YAML front matter, filter items due in the next 48 hours or in_progress / blocked.
// Produces { pushoverMessage, ntfyFamily, ntfyByAudience } for downstream nodes.
const yaml = require('js-yaml');
const raw = $input.first().json.data || $input.first().json.body || $input.first().json;
const text = typeof raw === 'string' ? raw : '';
const m = text.match(/^---\n([\s\S]*?)\n---/);
if (!m) {
  return [{ json: { error: 'No YAML front matter found in PROJECT-TIMELINE.md', textLength: text.length } }];
}
const meta = yaml.load(m[1]);
const items = meta.items || [];
const now = new Date();
const soon = new Date(now.getTime() + 48 * 60 * 60 * 1000);

function parseDate(d) {
  if (!d) return null;
  const dt = new Date(d + 'T00:00:00');
  return isNaN(dt.getTime()) ? null : dt;
}

const today = items.filter(it => {
  if (it.status === 'shipped' || it.status === 'deferred') return false;
  if (it.status === 'in_progress' || it.status === 'blocked') return true;
  const due = parseDate(it.due);
  if (!due) return false;
  return due <= soon;
});

const byStatus = { in_progress: [], blocked: [], due_today: [], due_soon: [], shipped_recently: [] };
for (const it of today) {
  const due = parseDate(it.due);
  if (it.status === 'in_progress') byStatus.in_progress.push(it);
  else if (it.status === 'blocked') byStatus.blocked.push(it);
  else if (due && due.toDateString() === now.toDateString()) byStatus.due_today.push(it);
  else byStatus.due_soon.push(it);
}

// Recently shipped (last 48h) - celebrate
const recently = items.filter(it => {
  if (it.status !== 'shipped' || !it.shipped_at) return false;
  const dt = parseDate(it.shipped_at);
  if (!dt) return false;
  return (now - dt) <= 48 * 60 * 60 * 1000;
});
byStatus.shipped_recently = recently;

function fmtItem(it) {
  const due = it.due ? ` (due ${it.due})` : '';
  const owner = it.owner ? ` [${it.owner}]` : '';
  return `- ${it.id}: ${it.title}${due}${owner}`;
}

const lines = [];
lines.push(`PoeTech project digest - ${now.toISOString().slice(0, 10)}`);
lines.push(`Vacation start: ${meta.vacation_start} | Family launch target: ${meta.family_launch_target}`);
lines.push('');
if (byStatus.in_progress.length) {
  lines.push(`IN PROGRESS (${byStatus.in_progress.length}):`);
  byStatus.in_progress.forEach(it => lines.push(fmtItem(it)));
  lines.push('');
}
if (byStatus.blocked.length) {
  lines.push(`BLOCKED (${byStatus.blocked.length}) - unblock me:`);
  byStatus.blocked.forEach(it => lines.push(fmtItem(it)));
  lines.push('');
}
if (byStatus.due_today.length) {
  lines.push(`DUE TODAY (${byStatus.due_today.length}):`);
  byStatus.due_today.forEach(it => lines.push(fmtItem(it)));
  lines.push('');
}
if (byStatus.due_soon.length) {
  lines.push(`DUE NEXT 48H (${byStatus.due_soon.length}):`);
  byStatus.due_soon.forEach(it => lines.push(fmtItem(it)));
  lines.push('');
}
if (byStatus.shipped_recently.length) {
  lines.push(`SHIPPED LAST 48H (${byStatus.shipped_recently.length}):`);
  byStatus.shipped_recently.forEach(it => lines.push(fmtItem(it)));
  lines.push('');
}
if (!byStatus.in_progress.length && !byStatus.blocked.length && !byStatus.due_today.length && !byStatus.due_soon.length) {
  lines.push('Nothing due in the next 48h. Phase clear. Sip coffee.');
}

const pushoverMessage = lines.join('\n');

// Family-visible items go to ntfy family-ops
const familyVisible = today.filter(it => it.family_visible === true);
const ntfyFamilyLines = ['Family update'];
familyVisible.forEach(it => {
  const due = it.due ? ` (due ${it.due})` : '';
  ntfyFamilyLines.push(`- ${it.title}${due}`);
});
const ntfyFamily = familyVisible.length ? ntfyFamilyLines.join('\n') : null;

// Per-audience routing
const byAudience = {};
for (const it of today) {
  if (!it.audience) continue;
  if (!byAudience[it.audience]) byAudience[it.audience] = [];
  byAudience[it.audience].push(it);
}
const ntfyByAudience = Object.entries(byAudience).map(([topic, list]) => ({
  topic,
  message: `For ${topic}:\n` + list.map(it => `- ${it.title}${it.due ? ` (due ${it.due})` : ''}`).join('\n')
}));

return [{ json: { pushoverMessage, ntfyFamily, ntfyByAudience, counts: { in_progress: byStatus.in_progress.length, blocked: byStatus.blocked.length, due_today: byStatus.due_today.length, due_soon: byStatus.due_soon.length, shipped_recently: byStatus.shipped_recently.length } } }];
